        .init(id:"prep-united-states-history", objectiveID:"prep-united-states-history-evidence", examTitle:"AP U.S. History", frameworkEdition:"Course and Exam Description · effective Fall 2026 · checked 2026-10-19 for 2026–27", frameworkURL:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-us-history-course-and-exam-description.pdf")!, location:"Unit 3, Topic 3.8; Skill 3.A Claims and Evidence in Sources", units:["Unit 1: Period 1: 1491–1607","Unit 2: Period 2: 1607–1754","Unit 3: Period 3: 1754–1800","Unit 4: Period 4: 1800–1848","Unit 5: Period 5: 1844–1877","Unit 6: Period 6: 1865–1898","Unit 7: Period 7: 1890–1945","Unit 8: Period 8: 1945–1980","Unit 9: Period 9: 1980–Present"], selectedUnit:"Unit 3: Period 3: 1754–1800", coverage:"One selected-topic module with original instruction, four practice questions, and a written self-review. Selected content within Unit 3: Period 3: 1754–1800. This does not cover the full unit, course or exam.", skill:"sourcing, contextualizing and qualifying a historical claim", writtenTask:"Using the linked Delaware petition, write a claim about what its authors hoped ratification would accomplish. Identify one specific source detail, connect the claim to the Articles-era context, and explain why the source cannot establish unanimous public support.", rubric:["State a defensible claim about the petitioners’ position.","Use a specific detail actually present in the archive source.","Explain a relevant Articles-era issue rather than listing an unrelated date.","Distinguish petitioners and convention delegates from all residents."]),
