    public static let content: LearningContent = {
        var courses: [Course] = []
        var objectives: [LearningObjective] = []
        var lessons: [LessonMaterial] = []
        var questions: [PracticeQuestion] = []
        let source0 = SourceReference(title:"AP Biology Course and Exam Description", publisher:"College Board · framework reference", url:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-biology-course-and-exam-description.pdf")!, accessedOn:Date(timeIntervalSince1970:1792368000))
        courses.append(.init(id:"prep-biology", title:"Biology · AP® preparation", subtitle:"Use an osmosis experiment as evidence", subject:.biology, level:.apPreparation, symbolName:"text.book.closed", estimatedMinutes:35, objectiveIDs:["prep-biology-evidence"], source:source0, curriculum:.init(title:"Course and Exam Description · effective Fall 2025 · checked 2026-10-19 for 2026–27", provider:"College Board", url:source0.url, license:"Linked framework; no College Board questions reproduced", attribution:"Original independent instruction by First State Lens. College Board is not affiliated with this app.")))
        objectives.append(.init(id:"prep-biology-evidence", title:"Use an osmosis experiment as evidence", summary:"Explain movement across a selectively permeable membrane, then use a mass-change experiment to estimate an isotonic condition. This selected module develops a biological explanation and tests what the data can support.", order:0, prerequisiteIDs:[], source:source0))
        lessons.append(.init(objectiveID:"prep-biology-evidence", overview:"Explain movement across a selectively permeable membrane, then use a mass-change experiment to estimate an isotonic condition. This selected module develops a biological explanation and tests what the data can support.", keyIdeas:["Water movement depends on the concentration of solutes that cannot cross the membrane.","An isotonic estimate is a model inferred from data, not a direct measurement of every cell.","Controls, repeated samples and uncertainty belong in an explanation."], notes:[.init(title:"Build the mechanism", body:"A membrane is a selective boundary. Small nonpolar molecules can cross its lipid region more readily than ions. Water can move across membranes, including through aquaporins. In a simple model with impermeable solutes and equal pressure, water moves toward the side with higher solute concentration. Water still moves in both directions; osmosis describes the net movement. A hypotonic external solution can cause a cell to gain water. A hypertonic solution can cause water loss. Tonicity depends on solutes that remain separated by the membrane, so a solute that crosses freely can produce a different long-term response. Plant cell walls constrain expansion and allow pressure to build. Do not predict that every cell simply bursts in dilute water."),.init(title:"Turn observations into a model", body:"Imagine equal potato cylinders placed in sucrose solutions. The manipulated variable is external sucrose concentration; the response is percentage change in mass. Keep cylinder dimensions, exposure time, temperature, source tissue and blotting method consistent. Percentage change equals 100 × (final mass − initial mass) / initial mass. It enables a fairer comparison when initial masses differ slightly. Replicate each concentration and report variability. A zero mean change estimates the external concentration at which this tissue has no detectable net water gain under these conditions. It does not prove the tissue contains only sucrose or that every cell has exactly that concentration."),.init(title:"Worked data example", body:"Illustrative data, not an actual study: external sucrose concentration (M) 0.0, 0.2, 0.4, 0.6; mean mass change (%) +12, +5, −3, −10. The zero crossing falls between 0.2 and 0.4 M. Linear interpolation over that interval gives 0.2 + (5/8) × 0.2 = 0.325 M. Report about 0.33 M as an estimate, not an exact intracellular value. Plot concentration on the horizontal axis and mass change on the vertical axis. An outlier should prompt a check of tissue damage or blotting, not automatic deletion. More concentrations near the crossing would improve resolution."),.init(title:"Check the explanation", body:"A strong claim connects three things: the direction of the concentration difference, the membrane’s selective permeability, and the observed mass change. A positive mass change supports net water entry. It does not by itself show active transport, because water movement need not consume cellular ATP. If the graph has no zero crossing in the tested range, state the limit and propose a wider or better targeted range. The lesson supports an inference from a simplified system; living tissues also experience pressure and mixed solutes.")], video:nil, readingURL:source0.url, attribution:"Original explanations, examples and practice by First State Lens. Framework linked for reference; no official exam questions reproduced."))
        questions.append(.init(id:"prep-biology-evidence-q1", objectiveID:"prep-biology-evidence", prompt:"Which external concentration is closest to the estimated zero mass-change condition?", choices:[.init(id:"a", text:"0.33 M"),.init(id:"b", text:"0.00 M"),.init(id:"c", text:"0.60 M"),.init(id:"d", text:"1.20 M")], correctChoiceID:"a", explanation:"Zero lies between +5% at 0.2 M and −3% at 0.4 M. Interpolation gives 0.325 M.", source:source0))
        questions.append(.init(id:"prep-biology-evidence-q2", objectiveID:"prep-biology-evidence", prompt:"Which observation supports net water entry?", choices:[.init(id:"a", text:"Only an increase in the solution label"),.init(id:"b", text:"A negative percentage mass change"),.init(id:"c", text:"The presence of sucrose alone"),.init(id:"d", text:"A positive percentage mass change")], correctChoiceID:"d", explanation:"Mass gain, under controlled conditions, is evidence consistent with net water entry into the tissue.", source:source0))
        questions.append(.init(id:"prep-biology-evidence-q3", objectiveID:"prep-biology-evidence", prompt:"Why use equal exposure times?", choices:[.init(id:"a", text:"To remove the need for replication"),.init(id:"b", text:"To make sucrose permeable"),.init(id:"c", text:"To prevent time from confounding the concentration comparison"),.init(id:"d", text:"To force all cylinders to gain the same mass")], correctChoiceID:"c", explanation:"Different exposure times could alter the amount of water movement independently of solution concentration.", source:source0))
        questions.append(.init(id:"prep-biology-evidence-q4", objectiveID:"prep-biology-evidence", prompt:"What does a zero mean mass change establish?", choices:[.init(id:"a", text:"The membrane is impermeable to water"),.init(id:"b", text:"No detectable net gain or loss under these conditions"),.init(id:"c", text:"Every cell has exactly 0.325 M sucrose"),.init(id:"d", text:"Water molecules have stopped moving")], correctChoiceID:"b", explanation:"A net measurement can be zero while molecules continue exchanging; tissue composition is not directly measured.", source:source0))
        let source1 = SourceReference(title:"AP Chemistry Course and Exam Description", publisher:"College Board · framework reference", url:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-chemistry-course-and-exam-description.pdf")!, accessedOn:Date(timeIntervalSince1970:1792368000))
        courses.append(.init(id:"prep-chemistry", title:"Chemistry · AP® preparation", subtitle:"Explain a periodic trend with a model", subject:.chemistry, level:.apPreparation, symbolName:"text.book.closed", estimatedMinutes:35, objectiveIDs:["prep-chemistry-evidence"], source:source1, curriculum:.init(title:"Course and Exam Description · effective Fall 2024 · checked 2026-10-19 for 2026–27", provider:"College Board", url:source1.url, license:"Linked framework; no College Board questions reproduced", attribution:"Original independent instruction by First State Lens. College Board is not affiliated with this app.")))
        objectives.append(.init(id:"prep-chemistry-evidence", title:"Explain a periodic trend with a model", summary:"Use charge, distance and shielding to explain changes in atomic radius and first ionization energy. Then evaluate a comparison where a memorized arrow gives an incomplete explanation.", order:0, prerequisiteIDs:[], source:source1))
        lessons.append(.init(objectiveID:"prep-chemistry-evidence", overview:"Use charge, distance and shielding to explain changes in atomic radius and first ionization energy. Then evaluate a comparison where a memorized arrow gives an incomplete explanation.", keyIdeas:["Electrostatic attraction depends on nuclear charge and electron distance.","Shielding and shell structure explain why a trend is not a simple count of protons.","Measured exceptions help test the limits of a general trend."], notes:[.init(title:"From structure to force", body:"An atom’s nucleus attracts its electrons. Coulomb’s model says that opposite charges attract more strongly at smaller separation and with larger charge magnitude. In a many-electron atom, electron–electron interactions partly shield outer electrons from the nucleus. Effective nuclear charge is a useful simplified description of the attraction an electron experiences; it is not a second physical nucleus. Across a main-group period, nuclear charge increases while electrons enter the same principal shell. Shielding does not fully cancel the extra nuclear charge, so radii generally decrease and outer electrons are often harder to remove. Down a group, an added principal shell increases typical valence-electron distance and shielding, so atoms generally become larger."),.init(title:"Distinguish the measured quantities", body:"Atomic radius is inferred using a defined bonding or structural context; an electron cloud has no hard surface. First ionization energy is the energy needed to remove an electron from a neutral gas-phase atom. It is an energy change, not the attractive force itself. A smaller radius and stronger effective attraction often correspond to a larger first ionization energy, but subshell energies and electron pairing produce exceptions. State which quantity is being compared and give a particle-level reason. “It is farther right” locates the element without explaining the mechanism."),.init(title:"Worked comparison", body:"Sodium and magnesium occupy the same period. Magnesium has one more proton, and its valence electrons occupy the same principal shell as sodium’s. Greater effective nuclear attraction explains magnesium’s smaller typical atomic radius and higher first ionization energy. Now compare magnesium and aluminum: aluminum’s first removed electron occupies a 3p subshell rather than magnesium’s 3s subshell. Its higher-energy orbital helps explain why aluminum’s first ionization energy is lower despite the across-period generalization. The exception does not mean the charge model fails; it means shell and subshell structure must be included."),.init(title:"Use successive removals", body:"Successive ionization energies increase because each removal leaves a more positively charged ion. A particularly large jump often indicates that the next electron would come from an inner shell after valence electrons have been removed. Illustrative values in arbitrary units are 6, 12, 80, 110. The jump after the second removal is consistent with two relatively accessible valence electrons in a main-group atom. It does not identify an element uniquely. Do not compare successive removal energies as though each began with a neutral atom.")], video:nil, readingURL:source1.url, attribution:"Original explanations, examples and practice by First State Lens. Framework linked for reference; no official exam questions reproduced."))
        questions.append(.init(id:"prep-chemistry-evidence-q1", objectiveID:"prep-chemistry-evidence", prompt:"What best explains the smaller typical radius of Mg compared with Na?", choices:[.init(id:"a", text:"Greater effective attraction within the same principal shell"),.init(id:"b", text:"An extra principal shell in Mg"),.init(id:"c", text:"Complete disappearance of shielding"),.init(id:"d", text:"A repulsive nucleus")], correctChoiceID:"a", explanation:"Additional nuclear charge is not fully canceled by shielding within the same period.", source:source1))
        questions.append(.init(id:"prep-chemistry-evidence-q2", objectiveID:"prep-chemistry-evidence", prompt:"First ionization energy refers to removal from which species?", choices:[.init(id:"a", text:"Any solid crystal without specifying structure"),.init(id:"b", text:"An already doubly charged cation"),.init(id:"c", text:"A neutron"),.init(id:"d", text:"A neutral gas-phase atom")], correctChoiceID:"d", explanation:"The defined first step begins with a neutral atom in the gas phase.", source:source1))
        questions.append(.init(id:"prep-chemistry-evidence-q3", objectiveID:"prep-chemistry-evidence", prompt:"A large jump between second and third ionization energies suggests what for a main-group atom?", choices:[.init(id:"a", text:"No electrons remain after the second step"),.init(id:"b", text:"Exactly two neutrons"),.init(id:"c", text:"Two relatively accessible valence electrons"),.init(id:"d", text:"Three identical inner-shell electrons")], correctChoiceID:"c", explanation:"After two outer electrons are removed, the third may require removing an inner-shell electron.", source:source1))
        questions.append(.init(id:"prep-chemistry-evidence-q4", objectiveID:"prep-chemistry-evidence", prompt:"Why can Al have a lower first ionization energy than Mg?", choices:[.init(id:"a", text:"All across-period trends must be reversed"),.init(id:"b", text:"The removed 3p electron is higher in energy than a 3s electron"),.init(id:"c", text:"Al has no nuclear charge"),.init(id:"d", text:"Al has fewer protons than Mg")], correctChoiceID:"b", explanation:"Subshell structure qualifies the general increase in effective attraction across a period.", source:source1))
        let source2 = SourceReference(title:"AP Environmental Science Course and Exam Description", publisher:"College Board · framework reference", url:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-environmental-science-course-and-exam-description.pdf")!, accessedOn:Date(timeIntervalSince1970:1792368000))
        courses.append(.init(id:"prep-environmental-science", title:"Environmental Science · AP® preparation", subtitle:"Account for energy through an ecosystem", subject:.biology, level:.apPreparation, symbolName:"text.book.closed", estimatedMinutes:35, objectiveIDs:["prep-environmental-science-evidence"], source:source2, curriculum:.init(title:"Course and Exam Description · effective Fall 2026 · checked 2026-10-19 for 2026–27", provider:"College Board", url:source2.url, license:"Linked framework; no College Board questions reproduced", attribution:"Original independent instruction by First State Lens. College Board is not affiliated with this app.")))
        objectives.append(.init(id:"prep-environmental-science-evidence", title:"Account for energy through an ecosystem", summary:"Separate gross and net primary productivity, track units, and evaluate the limitations of trophic-transfer estimates. Use a coastal wetland as a model context without treating illustrative data as Delaware field measurements.", order:0, prerequisiteIDs:[], source:source2))
        lessons.append(.init(objectiveID:"prep-environmental-science-evidence", overview:"Separate gross and net primary productivity, track units, and evaluate the limitations of trophic-transfer estimates. Use a coastal wetland as a model context without treating illustrative data as Delaware field measurements.", keyIdeas:["Net primary productivity is gross production minus producer respiration.","Energy flows through ecosystems while matter cycles.","Transfer efficiency is an estimate that varies among systems."], notes:[.init(title:"Draw the accounting boundary", body:"Primary producers convert external energy into chemical energy. Gross primary productivity (GPP) is the rate at which producers fix that energy; producer respiration uses part of it to sustain the producers. Net primary productivity (NPP) is the portion remaining as new producer biomass after respiration. Thus NPP = GPP − R. A rate must include a time interval and often an area. Kilojoules per square meter per year differs from a standing stock measured only in kilojoules per square meter. Biomass can be consumed, enter detrital pathways, or accumulate; NPP is not a promise that all energy reaches herbivores."),.init(title:"Worked coastal model", body:"For an illustrative marsh plot, suppose GPP is 18,000 kJ m⁻² yr⁻¹ and producer respiration is 11,000 kJ m⁻² yr⁻¹. NPP is 7,000 kJ m⁻² yr⁻¹. If herbivore production is 700 kJ m⁻² yr⁻¹, transfer efficiency from producer NPP to herbivore production is 700/7,000 × 100 = 10%. Across 20 m², annual producer net production is 140,000 kJ. Keep the area conversion separate from the efficiency calculation. These values are invented for calculation practice, not a measurement from a Delaware marsh."),.init(title:"Explain the missing energy", body:"Organisms use energy for maintenance and movement; respiration ultimately disperses much of it as heat. Some biomass is not eaten, and some eaten material is not assimilated. A food-web diagram that shows only predator–prey arrows can omit detritus and decomposers. Unlike matter, usable energy is not recycled indefinitely to producers. The often-used 10% transfer rule is a classroom approximation. Real efficiency depends on organisms, temperature, diet and how production is measured. Use a stated efficiency for an estimate, and label that assumption."),.init(title:"Test an environmental claim", body:"A proposal might claim that doubling nutrient input will double NPP. The energy budget alone cannot establish that causal effect. Light, water, temperature, nutrient limitation, species composition and disturbance also matter. A stronger design compares replicated plots under controlled nutrient treatments while measuring relevant confounders and unintended consequences, such as downstream oxygen demand from decomposition. A before–after comparison without an untreated reference could mix the effect of a treatment with a seasonal shift. When applying the model locally, use an official monitoring source and retain its dates, sites and measurement units.")], video:nil, readingURL:source2.url, attribution:"Original explanations, examples and practice by First State Lens. Framework linked for reference; no official exam questions reproduced."))
        questions.append(.init(id:"prep-environmental-science-evidence-q1", objectiveID:"prep-environmental-science-evidence", prompt:"What is NPP when GPP is 18,000 and producer respiration is 11,000 in the same units?", choices:[.init(id:"a", text:"7,000"),.init(id:"b", text:"29,000"),.init(id:"c", text:"11,000"),.init(id:"d", text:"0.61")], correctChoiceID:"a", explanation:"Subtract producer respiration from gross production: 18,000 − 11,000 = 7,000.", source:source2))
        questions.append(.init(id:"prep-environmental-science-evidence-q2", objectiveID:"prep-environmental-science-evidence", prompt:"What is 8% of 7,000 kJ m⁻² yr⁻¹?", choices:[.init(id:"a", text:"875 kJ m⁻² yr⁻¹"),.init(id:"b", text:"5,600 kJ m⁻² yr⁻¹"),.init(id:"c", text:"56,000 kJ m⁻² yr⁻¹"),.init(id:"d", text:"560 kJ m⁻² yr⁻¹")], correctChoiceID:"d", explanation:"Multiply 7,000 by 0.08. The units remain a production rate per area.", source:source2))
        questions.append(.init(id:"prep-environmental-science-evidence-q3", objectiveID:"prep-environmental-science-evidence", prompt:"Why does energy available as production usually decline at higher trophic levels?", choices:[.init(id:"a", text:"All heat is returned as food to plants"),.init(id:"b", text:"Every organism has the same metabolism"),.init(id:"c", text:"Respiration and incomplete consumption or assimilation reduce transfer"),.init(id:"d", text:"Energy is destroyed by predators")], correctChoiceID:"c", explanation:"Energy is conserved physically but much is dispersed as heat or follows other pathways.", source:source2))
        questions.append(.init(id:"prep-environmental-science-evidence-q4", objectiveID:"prep-environmental-science-evidence", prompt:"Which addition best improves a fertilizer experiment?", choices:[.init(id:"a", text:"Assuming the 10% rule is exact"),.init(id:"b", text:"Replicated untreated comparison plots measured over the same season"),.init(id:"c", text:"Only a photograph after fertilization"),.init(id:"d", text:"A larger fertilizer dose with no measurements")], correctChoiceID:"b", explanation:"Contemporaneous controls and replication help separate treatment effects from variation.", source:source2))
        let source3 = SourceReference(title:"AP Calculus AB Course and Exam Description", publisher:"College Board · framework reference", url:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-calculus-ab-and-bc-course-and-exam-description.pdf")!, accessedOn:Date(timeIntervalSince1970:1792368000))
        courses.append(.init(id:"prep-calculus-ab", title:"Calculus AB · AP® preparation", subtitle:"Find a limit without filling the hole", subject:.mathematics, level:.apPreparation, symbolName:"text.book.closed", estimatedMinutes:35, objectiveIDs:["prep-calculus-ab-evidence"], source:source3, curriculum:.init(title:"Course and Exam Description · effective Fall 2020 · checked 2026-10-19 for 2026–27", provider:"College Board", url:source3.url, license:"Linked framework; no College Board questions reproduced", attribution:"Original independent instruction by First State Lens. College Board is not affiliated with this app.")))
        objectives.append(.init(id:"prep-calculus-ab-evidence", title:"Find a limit without filling the hole", summary:"Distinguish the value of a function from the value it approaches, then justify algebraic simplification on a punctured neighborhood. Practice removable and nonremovable discontinuities.", order:0, prerequisiteIDs:[], source:source3))
        lessons.append(.init(objectiveID:"prep-calculus-ab-evidence", overview:"Distinguish the value of a function from the value it approaches, then justify algebraic simplification on a punctured neighborhood. Practice removable and nonremovable discontinuities.", keyIdeas:["A limit describes nearby behavior, not necessarily the value at the point.","Cancellation is valid only where the canceled factor is nonzero.","Two-sided limits require agreement of both one-sided limits."], notes:[.init(title:"Ask the nearby question", body:"The statement lim x→a f(x) = L means function values can be made arbitrarily close to L by taking x sufficiently close to a, with x not equal to a. Whether f(a) exists is a different question. A graph can approach one height while a filled point sits at another height. Continuity at a requires that f(a) exists, the limit exists, and they are equal. Substitution is efficient when a function is continuous at the point. An indeterminate form such as 0/0 is a signal to analyze further; it is not a numerical answer and does not prove that a limit fails to exist."),.init(title:"Worked removable discontinuity", body:"Let f(x) = (x² − 9)/(x − 3) for x ≠ 3. Factor the numerator into (x − 3)(x + 3). For x ≠ 3, cancellation gives f(x) = x + 3, so the limit as x approaches 3 is 6. The simplification establishes equality near 3, not at 3. The original expression is still undefined at 3. Define a new function g with g(x)=f(x) when x≠3 and g(3)=6; g is continuous there. If instead g(3)=10, its limit remains 6 but it is not continuous. The nearby behavior did not change when the single value changed."),.init(title:"Compare a nonremovable case", body:"Consider h(x) = |x|/x for x≠0. For positive x, h(x)=1; for negative x, h(x)=−1. The right-hand limit at zero is 1 and the left-hand limit is −1. Because they disagree, the two-sided limit does not exist. Giving h(0) any value cannot repair that jump. A table with only positive inputs would conceal half the evidence. Likewise, a numerical table cannot prove a limit by itself: it samples finitely many nearby points. Use the expression and definitions to justify the conclusion when available."),.init(title:"Choose and communicate a method", body:"First identify the point and check direct substitution. If a rational expression produces 0/0, inspect factoring or another algebraic transformation valid near the point. State excluded values before canceling. Then evaluate the simplified nearby expression. Check one-sided behavior when absolute values, piecewise definitions, or vertical asymptotes are involved. Never divide by zero, and do not use an undefined expression as an equation step. A clear solution ends by distinguishing the requested limit from the original function value. This module does not cover derivatives, integration, or a complete AP examination.")], video:nil, readingURL:source3.url, attribution:"Original explanations, examples and practice by First State Lens. Framework linked for reference; no official exam questions reproduced."))
        questions.append(.init(id:"prep-calculus-ab-evidence-q1", objectiveID:"prep-calculus-ab-evidence", prompt:"What is lim x→3 (x²−9)/(x−3)?", choices:[.init(id:"a", text:"6"),.init(id:"b", text:"0"),.init(id:"c", text:"3"),.init(id:"d", text:"It cannot exist because the expression is undefined at 3")], correctChoiceID:"a", explanation:"The expression equals x+3 whenever x≠3, so nearby values approach 6.", source:source3))
        questions.append(.init(id:"prep-calculus-ab-evidence-q2", objectiveID:"prep-calculus-ab-evidence", prompt:"What restriction accompanies canceling x−3?", choices:[.init(id:"a", text:"x must equal 3"),.init(id:"b", text:"x must be positive at every point"),.init(id:"c", text:"There is no restriction"),.init(id:"d", text:"x must not equal 3")], correctChoiceID:"d", explanation:"Cancellation divides by x−3 and is valid only when this factor is nonzero.", source:source3))
        questions.append(.init(id:"prep-calculus-ab-evidence-q3", objectiveID:"prep-calculus-ab-evidence", prompt:"For |x|/x at 0, why does the two-sided limit fail?", choices:[.init(id:"a", text:"Every undefined function lacks all limits"),.init(id:"b", text:"The right limit is zero"),.init(id:"c", text:"The left limit is −1 and the right limit is 1"),.init(id:"d", text:"The numerator is always negative")], correctChoiceID:"c", explanation:"The two one-sided limits disagree.", source:source3))
        questions.append(.init(id:"prep-calculus-ab-evidence-q4", objectiveID:"prep-calculus-ab-evidence", prompt:"If g agrees with x+3 except g(3)=10, what is lim x→3 g(x)?", choices:[.init(id:"a", text:"0"),.init(id:"b", text:"6"),.init(id:"c", text:"10"),.init(id:"d", text:"13")], correctChoiceID:"b", explanation:"Changing a value at a single point does not change nearby behavior.", source:source3))
        let source4 = SourceReference(title:"AP Statistics Course and Exam Description", publisher:"College Board · framework reference", url:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-statistics-course-and-exam-description.pdf")!, accessedOn:Date(timeIntervalSince1970:1792368000))
        courses.append(.init(id:"prep-statistics", title:"Statistics · AP® preparation", subtitle:"Design a sample that answers the question", subject:.mathematics, level:.apPreparation, symbolName:"text.book.closed", estimatedMinutes:35, objectiveIDs:["prep-statistics-evidence"], source:source4, curriculum:.init(title:"Course and Exam Description · effective Fall 2026 · checked 2026-10-19 for 2026–27", provider:"College Board", url:source4.url, license:"Linked framework; no College Board questions reproduced", attribution:"Original independent instruction by First State Lens. College Board is not affiliated with this app.")))
        objectives.append(.init(id:"prep-statistics-evidence", title:"Design a sample that answers the question", summary:"Define a population and sampling frame, compare simple and stratified random samples, and analyze how selection and nonresponse can distort an estimate.", order:0, prerequisiteIDs:[], source:source4))
        lessons.append(.init(objectiveID:"prep-statistics-evidence", overview:"Define a population and sampling frame, compare simple and stratified random samples, and analyze how selection and nonresponse can distort an estimate.", keyIdeas:["In an SRS of size n, every sample of that size has equal selection probability.","Strata divide the population; random samples are drawn within each stratum.","A larger sample does not automatically remove systematic bias."], notes:[.init(title:"Define what is being estimated", body:"Suppose a school wants to estimate the proportion of all enrolled students who use its library weekly. The population is all enrolled students, the observational unit is an individual student, and the variable is whether that student used the library at least once during the specified week. A sampling frame lists units available for selection. A roster that omits students in a satellite program cannot represent all enrolled students even if selection from that roster is perfectly random. Define the reference week and wording before collecting responses so different respondents answer the same question."),.init(title:"Choose a sampling mechanism", body:"For a simple random sample (SRS) without replacement, label every eligible student once and use a random mechanism to choose n distinct labels. Every possible group of n labels must have the same chance of selection. Equal individual chances alone are not a sufficient definition: choosing an entire homeroom at random gives equal individual inclusion probabilities when homerooms have equal size, but many possible groups of n cannot be selected. A stratified design first divides students into nonoverlapping groups, such as grade levels, then takes a separate random sample within each grade. This can ensure representation and improve precision when library use differs by grade."),.init(title:"Worked allocation", body:"A model school has 1,000 students: 300 in grade 9, 250 in grade 10, 250 in grade 11 and 200 in grade 12. A proportionally allocated stratified sample of 100 takes 30, 25, 25 and 20 respectively, with random selection inside each grade. If instead 25 are taken from every grade, grade 12 students have a greater selection probability than grade 9 students. Equal allocation can still be a useful design, but estimating the overall school proportion requires accounting for the different population shares. Do not average subgroup percentages blindly when subgroup weights differ."),.init(title:"Separate sampling error from bias", body:"Random sampling produces variation across samples; it does not guarantee an estimate equals the population value. Nonresponse creates another problem: selected students who do not reply may differ systematically in library use from those who do. Surveying only students leaving the library creates selection bias that cannot be repaired simply by interviewing more library users. Follow-up with selected nonrespondents, clear wording and complete coverage improve the design. Random sampling supports generalization to the sampled population under suitable conditions; random assignment is the tool for supporting causal comparisons in an experiment. They solve different problems.")], video:nil, readingURL:source4.url, attribution:"Original explanations, examples and practice by First State Lens. Framework linked for reference; no official exam questions reproduced."))
        questions.append(.init(id:"prep-statistics-evidence-q1", objectiveID:"prep-statistics-evidence", prompt:"Which sample is proportionally allocated?", choices:[.init(id:"a", text:"30,25,25,20"),.init(id:"b", text:"25,25,25,25"),.init(id:"c", text:"50,20,20,10"),.init(id:"d", text:"100,0,0,0")], correctChoiceID:"a", explanation:"Each grade receives its population share of the 100 sampled students.", source:source4))
        questions.append(.init(id:"prep-statistics-evidence-q2", objectiveID:"prep-statistics-evidence", prompt:"What makes a design an SRS of size n?", choices:[.init(id:"a", text:"Only each student must have some chance"),.init(id:"b", text:"The first n names are selected"),.init(id:"c", text:"All respondents volunteer"),.init(id:"d", text:"Every possible sample of size n has the same chance")], correctChoiceID:"d", explanation:"The definition concerns equal probabilities for possible samples of the specified size.", source:source4))
        questions.append(.init(id:"prep-statistics-evidence-q3", objectiveID:"prep-statistics-evidence", prompt:"Why may surveying only library visitors overestimate weekly library use?", choices:[.init(id:"a", text:"Random assignment was used"),.init(id:"b", text:"The population cannot be defined"),.init(id:"c", text:"The sampling mechanism systematically favors users"),.init(id:"d", text:"The sample is necessarily too small to calculate any proportion")], correctChoiceID:"c", explanation:"The place of recruitment makes users more likely to be selected.", source:source4))
        questions.append(.init(id:"prep-statistics-evidence-q4", objectiveID:"prep-statistics-evidence", prompt:"What supports a causal comparison in an experiment?", choices:[.init(id:"a", text:"A strong correlation alone"),.init(id:"b", text:"Random assignment to treatments"),.init(id:"c", text:"Random selection alone"),.init(id:"d", text:"A large voluntary poll")], correctChoiceID:"b", explanation:"Random assignment balances potential confounding variables in expectation; selection addresses representation.", source:source4))
        let source5 = SourceReference(title:"AP Computer Science A Course and Exam Description", publisher:"College Board · framework reference", url:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-computer-science-a-course-and-exam-description.pdf")!, accessedOn:Date(timeIntervalSince1970:1792368000))
        courses.append(.init(id:"prep-computer-science-a", title:"Computer Science A · AP® preparation", subtitle:"Trace a loop and defend its boundaries", subject:.computerScience, level:.apPreparation, symbolName:"text.book.closed", estimatedMinutes:35, objectiveIDs:["prep-computer-science-a-evidence"], source:source5, curriculum:.init(title:"Course and Exam Description · effective Fall 2025 · checked 2026-10-19 for 2026–27", provider:"College Board", url:source5.url, license:"Linked framework; no College Board questions reproduced", attribution:"Original independent instruction by First State Lens. College Board is not affiliated with this app.")))
        objectives.append(.init(id:"prep-computer-science-a-evidence", title:"Trace a loop and defend its boundaries", summary:"Trace an accumulator through a counted loop, identify a boundary error, and write a short Java method with a testable contract. Code is analyzed and self-reviewed here; this app does not run Java.", order:0, prerequisiteIDs:[], source:source5))
        lessons.append(.init(objectiveID:"prep-computer-science-a-evidence", overview:"Trace an accumulator through a counted loop, identify a boundary error, and write a short Java method with a testable contract. Code is analyzed and self-reviewed here; this app does not run Java.", keyIdeas:["Initialization, condition and update determine which values a loop visits.","An accumulator summarizes work done so far.","Boundary tests expose errors that typical examples can miss."], notes:[.init(title:"Read the loop as a state machine", body:"A for loop performs its initializer once, checks the condition before each iteration, runs the body if the condition is true, and then performs the update. In Java, for (int i = 1; i <= 4; i++) visits 1, 2, 3 and 4. When the update makes i equal to 5, the next check fails. The body does not run for 5. A variable declared in the initializer is scoped to the loop. Trace the values that actually reach the body rather than counting punctuation or guessing from the final bound."),.init(title:"Worked accumulator trace", body:"Consider int total = 0; for (int i = 1; i <= 4; i++) { total += i; }. Before any body execution, total is 0. After i=1 it is 1; after i=2 it is 3; after i=3 it is 6; after i=4 it is 10. The useful invariant is that after processing i, total equals the sum of integers from 1 through i. Changing <= to < omits 4 and gives 6. Moving total=0 inside the loop destroys accumulation because earlier work is discarded each iteration. A trace table should include the condition check and the update, especially when analyzing termination."),.init(title:"Write a method with a contract", body:"A method sumTo(int n) can return the sum from 1 through n for n>=0: int total = 0; for (int i = 1; i <= n; i++) { total += i; } return total;. For n=0, the body executes zero times and the return is 0. That is consistent with an empty sum. For a negative n, the same code also returns 0, but whether that is acceptable depends on the stated contract. Do not silently widen a precondition while explaining correctness. Java int arithmetic has finite range; this simple method can overflow for sufficiently large n. A contract or wider representation must address that when building real software."),.init(title:"Design meaningful tests", body:"Test n=0 to verify zero iterations, n=1 to check the smallest positive case, and n=4 to test multiple updates. Expected results are 0, 1 and 10. A test for n=4 distinguishes < from <=; a test for 0 alone does not. For a method that sums only even integers up to n, n=5 and n=6 are useful adjacent cases because they exercise the inclusion boundary for an even endpoint. Explain why a test could reveal a particular defect. Passing a handful of examples supports confidence but does not replace reasoning about every allowed input.")], video:nil, readingURL:source5.url, attribution:"Original explanations, examples and practice by First State Lens. Framework linked for reference; no official exam questions reproduced."))
        questions.append(.init(id:"prep-computer-science-a-evidence-q1", objectiveID:"prep-computer-science-a-evidence", prompt:"What is total after summing i from 1 through 4 inclusively?", choices:[.init(id:"a", text:"10"),.init(id:"b", text:"6"),.init(id:"c", text:"4"),.init(id:"d", text:"0")], correctChoiceID:"a", explanation:"The accumulator becomes 1,3,6,10 across the four body executions.", source:source5))
        questions.append(.init(id:"prep-computer-science-a-evidence-q2", objectiveID:"prep-computer-science-a-evidence", prompt:"What changes when i<=4 becomes i<4?", choices:[.init(id:"a", text:"The loop runs once more"),.init(id:"b", text:"The initializer runs on every iteration"),.init(id:"c", text:"The result becomes 14"),.init(id:"d", text:"The term 4 is omitted")], correctChoiceID:"d", explanation:"The condition is false when i reaches 4, so the body handles only 1,2,3.", source:source5))
        questions.append(.init(id:"prep-computer-science-a-evidence-q3", objectiveID:"prep-computer-science-a-evidence", prompt:"Why initialize an accumulator before the loop?", choices:[.init(id:"a", text:"To reset all earlier terms after each iteration"),.init(id:"b", text:"To prevent all integer overflow"),.init(id:"c", text:"To preserve earlier partial results across iterations"),.init(id:"d", text:"To make the loop skip its condition")], correctChoiceID:"c", explanation:"An outside initialization starts the total once; resetting inside loses accumulated work.", source:source5))
        questions.append(.init(id:"prep-computer-science-a-evidence-q4", objectiveID:"prep-computer-science-a-evidence", prompt:"Which pair tests both zero iterations and inclusion of an even endpoint for sumEvenTo?", choices:[.init(id:"a", text:"n=5 and n=7"),.init(id:"b", text:"n=0 and n=6"),.init(id:"c", text:"n=3 and n=5"),.init(id:"d", text:"n=1 and n=3")], correctChoiceID:"b", explanation:"n=0 checks no work; n=6 checks that the even upper endpoint is included.", source:source5))
        let source6 = SourceReference(title:"AP English Language and Composition Course and Exam Description", publisher:"College Board · framework reference", url:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-english-language-and-composition-course-and-exam-description.pdf")!, accessedOn:Date(timeIntervalSince1970:1792368000))
        courses.append(.init(id:"prep-english-language-and-composition", title:"English Language · AP® preparation", subtitle:"Connect a rhetorical choice to its purpose", subject:.english, level:.apPreparation, symbolName:"text.book.closed", estimatedMinutes:35, objectiveIDs:["prep-english-language-and-composition-evidence"], source:source6, curriculum:.init(title:"Course and Exam Description · effective Fall 2024 · checked 2026-10-19 for 2026–27", provider:"College Board", url:source6.url, license:"Linked framework; no College Board questions reproduced", attribution:"Original independent instruction by First State Lens. College Board is not affiliated with this app.")))
        objectives.append(.init(id:"prep-english-language-and-composition-evidence", title:"Connect a rhetorical choice to its purpose", summary:"Read an original public argument, distinguish a claim from its evidence, and explain how a specific choice addresses a specific audience. Move beyond naming a rhetorical device.", order:0, prerequisiteIDs:[], source:source6))
        lessons.append(.init(objectiveID:"prep-english-language-and-composition-evidence", overview:"Read an original public argument, distinguish a claim from its evidence, and explain how a specific choice addresses a specific audience. Move beyond naming a rhetorical device.", keyIdeas:["Audience and purpose shape the significance of a choice.","Evidence must be connected to a claim by reasoning.","A rhetorical analysis explains a choice’s function rather than merely praising persuasion."], notes:[.init(title:"Read the situation before the device", body:"A rhetorical situation includes a reason for speaking, a purpose, an audience, a context and a message. These elements constrain choices. A speaker asking a school board to extend library hours faces an audience that controls budgets and cares about access, safety and staffing. A successful analysis begins with what the speaker wants that audience to consider or do. It then selects details that matter for that situation. Naming a metaphor or an appeal to emotion does not explain how the argument operates. Distinguish the audience addressed in the text from every person who might happen to read it later."),.init(title:"Original practice passage", body:"The following is fictional, written for this module: “Board members, our final bell ends the school day, not the need for a quiet place to work. On Tuesdays, students waiting for the late activity bus already remain on campus. Opening the library until that bus leaves would turn waiting time into access to a desk, a charger, and a reference shelf. I am asking for a six-week Tuesday trial, staffed through the existing activity schedule, followed by a public review of attendance and cost. If the trial is not useful, we should revise it.” The proposal is limited and conditional. No attendance data or budget savings are established by the passage. Its claims should not be treated as verified information about any real school."),.init(title:"Worked analytical paragraph", body:"A defensible claim is that the speaker presents an extension as a bounded experiment to reduce the board’s concern about an indefinite commitment. The phrase “six-week Tuesday trial” narrows the proposal’s duration and frequency. The promise of a review makes future continuation depend on evidence. Commentary should explain why these features matter to a board responsible for cost and staffing. A weak analysis says only that the speaker “uses logic to persuade.” A stronger one connects an exact choice, its relationship to the audience’s responsibility, and the requested decision. Effects are reasoned interpretations, not proof that every listener was persuaded."),.init(title:"Build and qualify your interpretation", body:"Separate the passage’s main claim from supporting details. The main request is to authorize a trial; the existing late-bus schedule is offered as a practical reason to consider it. A counterargument could question whether the existing schedule actually includes available staff. The passage does not settle that issue, so an analysis can recognize both a strategic choice and a limit in its evidence. When writing your own paragraph, make a defensible claim, use a concise specific reference, and explain its function. Avoid retelling the entire passage or inventing facts about the speaker’s personal experience. This module is not a full synthesis, argument or timed examination course.")], video:nil, readingURL:source6.url, attribution:"Original explanations, examples and practice by First State Lens. Framework linked for reference; no official exam questions reproduced."))
        questions.append(.init(id:"prep-english-language-and-composition-evidence-q1", objectiveID:"prep-english-language-and-composition-evidence", prompt:"What is the passage’s main requested action?", choices:[.init(id:"a", text:"Authorize a limited Tuesday library trial"),.init(id:"b", text:"Promise permanent daily opening immediately"),.init(id:"c", text:"Eliminate the late bus"),.init(id:"d", text:"Prove all students prefer the library")], correctChoiceID:"a", explanation:"The speaker requests a six-week Tuesday trial with later review.", source:source6))
        questions.append(.init(id:"prep-english-language-and-composition-evidence-q2", objectiveID:"prep-english-language-and-composition-evidence", prompt:"What does the time limit primarily do in this rhetorical situation?", choices:[.init(id:"a", text:"Provides measured proof of savings"),.init(id:"b", text:"Shows that no staff are required"),.init(id:"c", text:"Establishes unanimous support"),.init(id:"d", text:"Reduces the audience’s concern about open-ended commitment")], correctChoiceID:"d", explanation:"A bounded trial lets a budget-responsible audience consider a reversible proposal.", source:source6))
        questions.append(.init(id:"prep-english-language-and-composition-evidence-q3", objectiveID:"prep-english-language-and-composition-evidence", prompt:"Which statement is commentary rather than simple summary?", choices:[.init(id:"a", text:"The speaker says six weeks"),.init(id:"b", text:"There is a late bus in the passage"),.init(id:"c", text:"The promised review makes continuation depend on evidence, addressing the board’s accountability role"),.init(id:"d", text:"The passage mentions a library")], correctChoiceID:"c", explanation:"Commentary explains why a choice matters to purpose and audience.", source:source6))
        questions.append(.init(id:"prep-english-language-and-composition-evidence-q4", objectiveID:"prep-english-language-and-composition-evidence", prompt:"Which supporting premise needs verification before adopting the proposal?", choices:[.init(id:"a", text:"The proposal says Tuesday"),.init(id:"b", text:"Suitable staff are available within the existing activity schedule"),.init(id:"c", text:"The passage contains a time limit"),.init(id:"d", text:"The request is addressed to board members")], correctChoiceID:"b", explanation:"The staffing assumption is an empirical issue that the fictional argument does not establish.", source:source6))
        let source7 = SourceReference(title:"AP U.S. History Course and Exam Description", publisher:"College Board · framework reference", url:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-us-history-course-and-exam-description.pdf")!, accessedOn:Date(timeIntervalSince1970:1792368000))
        courses.append(.init(id:"prep-united-states-history", title:"U.S. History · AP® preparation", subtitle:"Read ratification arguments in context", subject:.history, level:.apPreparation, symbolName:"text.book.closed", estimatedMinutes:35, objectiveIDs:["prep-united-states-history-evidence"], source:source7, curriculum:.init(title:"Course and Exam Description · effective Fall 2026 · checked 2026-10-19 for 2026–27", provider:"College Board", url:source7.url, license:"Linked framework; no College Board questions reproduced", attribution:"Original independent instruction by First State Lens. College Board is not affiliated with this app.")))
        objectives.append(.init(id:"prep-united-states-history-evidence", title:"Read ratification arguments in context", summary:"Explain the debate over ratification without flattening different positions into slogans. Use Delaware’s ratification petition as a source for what its authors argued, and separate that evidence from claims about everyone’s opinion.", order:0, prerequisiteIDs:[], source:source7))
        lessons.append(.init(objectiveID:"prep-united-states-history-evidence", overview:"Explain the debate over ratification without flattening different positions into slogans. Use Delaware’s ratification petition as a source for what its authors argued, and separate that evidence from claims about everyone’s opinion.", keyIdeas:["The Articles-era context helps explain arguments for revising national authority.","Source purpose and audience shape what a document can establish.","A unanimous convention vote is not proof of unanimous public opinion."], notes:[.init(title:"Place the debate in its period", body:"After independence, the Articles of Confederation created a national government with limited capacity to raise revenue and regulate interstate commerce. Disputes over public debt, trade and political authority helped shape demands for change. The Constitution drafted in 1787 proposed a stronger national government with separate branches and a federal structure. Ratification was contested. Supporters argued that a stronger union could address collective problems while constitutional checks limited abuse. Critics worried about consolidated power, representation and the protection of liberties. These were arguments among people with different interests and assumptions, not a single uniform “for” camp facing a single uniform “against” camp."),.init(title:"Use the Delaware source carefully", body:"The Delaware Public Archives provides a worksheet and lesson on a 1787 petition urging action toward ratification. Open the linked primary-source material and identify its date, authors or signers as recorded, its requested action, and the body it addressed. A petition is an attempt to influence a decision. Its language can establish what its authors wanted and what benefits they claimed. It cannot alone establish the views of residents who did not sign, excluded groups, or long-term economic effects. The archival lesson supplies context that should be distinguished from words actually present in the petition."),.init(title:"Worked claim and qualification", body:"A supported claim is that the petitioners associated an effective national union with political and economic stability. Evidence comes from their stated concerns and requested process, not merely from the fact that Delaware later ratified. A qualification is that the source is advocacy from a particular group. Delaware’s convention unanimously ratified on December 7, 1787; that describes the recorded convention decision. It does not mean that every resident was represented equally or agreed. To investigate broader opinion, compare petitions, correspondence, newspapers and convention records, attending to whose voices survive and whose are missing."),.init(title:"Write historical reasoning", body:"A contextual sentence should explain a relevant condition, such as revenue or interstate coordination under the Articles, then connect it to the debate. A sourcing sentence should explain how purpose or audience affects the document’s use, rather than just labeling it biased. All sources have perspectives; that does not make them useless. A causal claim that ratification immediately improved Delaware’s economy would require additional evidence over time and consideration of other causes. Keep the sequence clear: advocacy, political action, convention decision, and later consequences are different things to investigate.")], video:nil, readingURL:source7.url, attribution:"Original explanations, examples and practice by First State Lens. Framework linked for reference; no official exam questions reproduced."))
        questions.append(.init(id:"prep-united-states-history-evidence-q1", objectiveID:"prep-united-states-history-evidence", prompt:"Which context best helps explain demands for stronger national authority in 1787?", choices:[.init(id:"a", text:"Difficulties with revenue and interstate coordination under the Articles"),.init(id:"b", text:"The end of the Civil War"),.init(id:"c", text:"The New Deal"),.init(id:"d", text:"A presidential election in 1900")], correctChoiceID:"a", explanation:"The debate responded in part to perceived weaknesses of the Articles-era union.", source:source7))
        questions.append(.init(id:"prep-united-states-history-evidence-q2", objectiveID:"prep-united-states-history-evidence", prompt:"What does an advocacy petition directly support?", choices:[.init(id:"a", text:"A census of every resident’s opinion"),.init(id:"b", text:"Proof of later economic outcomes"),.init(id:"c", text:"Proof no opposing argument existed"),.init(id:"d", text:"A claim about the position its authors advanced")], correctChoiceID:"d", explanation:"Its purpose and content provide evidence of the petitioners’ argument, with limits on generalization.", source:source7))
        questions.append(.init(id:"prep-united-states-history-evidence-q3", objectiveID:"prep-united-states-history-evidence", prompt:"What follows from Delaware’s unanimous convention vote?", choices:[.init(id:"a", text:"All groups had equal political access"),.init(id:"b", text:"No resident had concerns"),.init(id:"c", text:"The convention’s recorded decision was unanimous"),.init(id:"d", text:"Every resident voted for ratification")], correctChoiceID:"c", explanation:"A delegate vote establishes a political decision, not universal public agreement.", source:source7))
        questions.append(.init(id:"prep-united-states-history-evidence-q4", objectiveID:"prep-united-states-history-evidence", prompt:"Which source set best tests how broadly an opinion was shared?", choices:[.init(id:"a", text:"Only a map of current county borders"),.init(id:"b", text:"Contemporary sources from multiple positions and groups"),.init(id:"c", text:"Only the same petition copied twice"),.init(id:"d", text:"A modern slogan")], correctChoiceID:"b", explanation:"Independent evidence representing differing voices can broaden and test the inference.", source:source7))
        let source8 = SourceReference(title:"AP U.S. Government Course and Exam Description", publisher:"College Board · framework reference", url:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-us-government-and-politics-course-and-exam-description.pdf")!, accessedOn:Date(timeIntervalSince1970:1792368000))
        courses.append(.init(id:"prep-united-states-government-and-politics", title:"U.S. Government · AP® preparation", subtitle:"Distinguish levels from branches of government", subject:.history, level:.apPreparation, symbolName:"text.book.closed", estimatedMinutes:35, objectiveIDs:["prep-united-states-government-and-politics-evidence"], source:source8, curriculum:.init(title:"Course and Exam Description · effective Fall 2026 · checked 2026-10-19 for 2026–27", provider:"College Board", url:source8.url, license:"Linked framework; no College Board questions reproduced", attribution:"Original independent instruction by First State Lens. College Board is not affiliated with this app.")))
        objectives.append(.init(id:"prep-united-states-government-and-politics-evidence", title:"Distinguish levels from branches of government", summary:"Map a public-policy scenario to national and state authority, then distinguish federalism from separation of powers. Build a short argument with a mechanism rather than a slogan.", order:0, prerequisiteIDs:[], source:source8))
        lessons.append(.init(objectiveID:"prep-united-states-government-and-politics-evidence", overview:"Map a public-policy scenario to national and state authority, then distinguish federalism from separation of powers. Build a short argument with a mechanism rather than a slogan.", keyIdeas:["Federalism allocates authority across national and state governments.","Separation of powers divides functions among branches within a government.","A policy preference is not itself evidence of constitutional authority."], notes:[.init(title:"Draw two different maps", body:"Federalism concerns the distribution of authority between national and state governments. Separation of powers concerns legislative, executive and judicial functions. These ideas can interact but answer different questions. A conflict between a state legislature and the national Congress involves levels. A dispute between Congress and the president involves branches at the national level. The Constitution grants enumerated powers to the national government and reserves undelegated powers to states or the people, subject to constitutional restrictions. Some powers, such as taxation, can be exercised by both levels within their respective authority. Local governments operate within state legal structures rather than as an additional sovereign level equivalent to states."),.init(title:"Worked policy scenario", body:"Imagine a national program that offers states money for a transportation project if they meet specified program conditions. A state decides whether to participate. This can illustrate intergovernmental cooperation using national financial resources and state administration. It does not mean every funding condition is constitutionally permissible. To analyze a specific dispute, identify the statute, source of authority, conditions and relevant constitutional doctrine. The fact that a policy concerns a school or road does not automatically make national action invalid or state action unlimited. Topic labels are not substitutes for analyzing powers."),.init(title:"Use an institution and a mechanism", body:"A response that says “checks and balances will solve it” is incomplete. Name the actor and describe the action. Congress may legislate and attach conditions within its authority; the executive administers the law; courts may review an actual legal dispute. State officials may decide whether to accept a voluntary program or may challenge a requirement through litigation. Whether a given challenge succeeds depends on the relevant law and facts. These examples show possible mechanisms, not advice about a current legal controversy. This lesson does not provide a complete account of required court cases or foundational documents."),.init(title:"Build an argument with limits", body:"Start by defining the principle relevant to the scenario. Then connect an exact fact to it: the national program supplies funds while states administer projects, illustrating shared policy implementation across levels. Acknowledge a meaningful counterpoint, such as the pressure funding can place on states. Avoid claiming that all national conditions erase state authority or that states can ignore any national law they dislike. For a stronger extended response, inspect the Constitution and the framework’s required documents, then explain how the chosen evidence supports the reasoning. Distinguish an argument about what policy should be from a claim about what constitutional authority permits.")], video:nil, readingURL:source8.url, attribution:"Original explanations, examples and practice by First State Lens. Framework linked for reference; no official exam questions reproduced."))
        questions.append(.init(id:"prep-united-states-government-and-politics-evidence-q1", objectiveID:"prep-united-states-government-and-politics-evidence", prompt:"Which comparison concerns federalism most directly?", choices:[.init(id:"a", text:"National and state authority"),.init(id:"b", text:"Congress and the president only"),.init(id:"c", text:"A judge and a jury"),.init(id:"d", text:"Two committees in the same legislature")], correctChoiceID:"a", explanation:"Federalism addresses authority across national and state governments.", source:source8))
        questions.append(.init(id:"prep-united-states-government-and-politics-evidence-q2", objectiveID:"prep-united-states-government-and-politics-evidence", prompt:"Which comparison concerns separation of powers?", choices:[.init(id:"a", text:"Two states set different policies"),.init(id:"b", text:"A state and national government share funding"),.init(id:"c", text:"Two cities share a road"),.init(id:"d", text:"Congress legislates while the president executes laws")], correctChoiceID:"d", explanation:"Legislation and execution are different branch functions at the same national level.", source:source8))
        questions.append(.init(id:"prep-united-states-government-and-politics-evidence-q3", objectiveID:"prep-united-states-government-and-politics-evidence", prompt:"Which power may be concurrent?", choices:[.init(id:"a", text:"The power of every city to coin money"),.init(id:"b", text:"The exclusive power of a private club to legislate"),.init(id:"c", text:"Taxation within each government’s lawful authority"),.init(id:"d", text:"The unrestricted power to ignore the Constitution")], correctChoiceID:"c", explanation:"National and state governments can both tax within their respective authority.", source:source8))
        questions.append(.init(id:"prep-united-states-government-and-politics-evidence-q4", objectiveID:"prep-united-states-government-and-politics-evidence", prompt:"What is needed before judging a particular funding condition constitutional?", choices:[.init(id:"a", text:"A generic reference to fairness"),.init(id:"b", text:"The legal authority, actual conditions and relevant doctrine"),.init(id:"c", text:"Only whether the policy seems popular"),.init(id:"d", text:"Only the word transportation")], correctChoiceID:"b", explanation:"A short policy description is insufficient to resolve a specific constitutional question.", source:source8))
        let source9 = SourceReference(title:"AP Psychology Course and Exam Description", publisher:"College Board · framework reference", url:URL(string:"https://apcentral.collegeboard.org/media/pdf/ap-psychology-course-and-exam-description.pdf")!, accessedOn:Date(timeIntervalSince1970:1792368000))
        courses.append(.init(id:"prep-psychology", title:"Psychology · AP® preparation", subtitle:"Evaluate a claim from a study design", subject:.socialScience, level:.apPreparation, symbolName:"text.book.closed", estimatedMinutes:35, objectiveIDs:["prep-psychology-evidence"], source:source9, curriculum:.init(title:"Course and Exam Description · effective Fall 2025 · checked 2026-10-19 for 2026–27", provider:"College Board", url:source9.url, license:"Linked framework; no College Board questions reproduced", attribution:"Original independent instruction by First State Lens. College Board is not affiliated with this app.")))
        objectives.append(.init(id:"prep-psychology-evidence", title:"Evaluate a claim from a study design", summary:"Analyze an original study scenario about practice and recall. Define variables, inspect assignment and sampling, and revise a conclusion to match the actual design.", order:0, prerequisiteIDs:[], source:source9))
        lessons.append(.init(objectiveID:"prep-psychology-evidence", overview:"Analyze an original study scenario about practice and recall. Define variables, inspect assignment and sampling, and revise a conclusion to match the actual design.", keyIdeas:["An operational definition states how a construct is measured or manipulated.","Random assignment and random sampling serve different purposes.","Ethics and measurement quality matter alongside statistical comparisons."], notes:[.init(title:"Translate a claim into variables", body:"Suppose a researcher asks whether retrieval practice improves recall of a short vocabulary list. “Learning” is broad; a usable operational definition might be the number of definitions correctly recalled on a specified test 24 hours after practice. The independent variable in an experiment is the manipulated practice condition, while the dependent variable is the measured recall score. The definition limits the inference: a difference on this task would not automatically establish a change in all academic learning or long-term achievement. Specify the materials, timing and scoring rule so another researcher could understand the procedure."),.init(title:"Compare two designs", body:"In a survey, students report how often they self-test and provide recent scores. A positive association could reflect a practice effect, but it could also reflect motivation, prior knowledge or reverse direction: students who already perform well might choose to self-test. In an experiment, volunteers can be randomly assigned to equal-duration retrieval practice or rereading. Random assignment helps balance potential confounders in expectation, supporting a causal comparison if other conditions are controlled. It does not make a convenience sample representative of every student. Random sampling would address that separate generalization question."),.init(title:"Worked result interpretation", body:"Illustrative results from a fictional experiment: 20 volunteers assigned to retrieval practice recall a mean of 14 of 20 definitions; 20 assigned to rereading recall a mean of 11. The observed difference is 3 definitions. These means alone do not show whether the difference is statistically reliable; variability and the analysis plan matter. Even a statistically supported result would apply most directly to the tested task, participants and conditions. Do not declare every participant improved by exactly three definitions. Group averages can conceal individual variation. An accurate initial conclusion reports the observed group difference and explains what additional analysis is needed."),.init(title:"Check ethics and credibility", body:"Participants need appropriate consent procedures, a right to withdraw, confidentiality and a risk-appropriate protocol; research involving minors requires additional safeguards. Avoid coercive recruitment or promises that participation will improve grades. A consistent scoring rule and blinded scoring where feasible reduce avoidable measurement bias. Preregistered questions and transparent reporting can reduce selective presentation, but no single badge guarantees a study’s conclusion. When reading a published study, inspect the sample, design, outcome, comparison and limitations before transferring a finding to a study routine. This activity is methodological practice, not a clinical assessment.")], video:nil, readingURL:source9.url, attribution:"Original explanations, examples and practice by First State Lens. Framework linked for reference; no official exam questions reproduced."))
        questions.append(.init(id:"prep-psychology-evidence-q1", objectiveID:"prep-psychology-evidence", prompt:"Which is an operational definition of the outcome?", choices:[.init(id:"a", text:"Number of definitions correctly recalled on a 20-item test after 24 hours"),.init(id:"b", text:"Being a better student"),.init(id:"c", text:"Intelligence in general"),.init(id:"d", text:"Liking the task")], correctChoiceID:"a", explanation:"This definition specifies the observation, measurement scale and time point.", source:source9))
        questions.append(.init(id:"prep-psychology-evidence-q2", objectiveID:"prep-psychology-evidence", prompt:"What does random assignment primarily address?", choices:[.init(id:"a", text:"Whether all population members were sampled"),.init(id:"b", text:"Whether every result is statistically significant"),.init(id:"c", text:"Whether consent is unnecessary"),.init(id:"d", text:"Potential confounding between treatment groups")], correctChoiceID:"d", explanation:"Random assignment balances potential confounders in expectation; it does not guarantee representation.", source:source9))
        questions.append(.init(id:"prep-psychology-evidence-q3", objectiveID:"prep-psychology-evidence", prompt:"The group means are 14 and 11. What can be stated directly?", choices:[.init(id:"a", text:"All students will benefit"),.init(id:"b", text:"The result is necessarily statistically significant"),.init(id:"c", text:"The observed mean difference is three definitions"),.init(id:"d", text:"Every volunteer gained three definitions")], correctChoiceID:"c", explanation:"The arithmetic difference is observed; stronger inferences require more information.", source:source9))
        questions.append(.init(id:"prep-psychology-evidence-q4", objectiveID:"prep-psychology-evidence", prompt:"Why can a survey association fail to show a practice effect?", choices:[.init(id:"a", text:"A large sample eliminates every confounder"),.init(id:"b", text:"Motivation or prior knowledge may influence both practice and scores"),.init(id:"c", text:"Associations can never be measured"),.init(id:"d", text:"Random assignment always occurred")], correctChoiceID:"b", explanation:"Uncontrolled variables and directionality can account for an observed association.", source:source9))
        return LearningContent(courses:courses, objectives:objectives, questions:questions, lessonMaterials:lessons)
    }()
}
